const tickers = $input.item.json.tickers || [];
const candidates = tickers.filter(t => {
  const price = t.day?.c || 0;
  const volume = t.day?.v || 0;
  return price >= 5 && volume >= 500000;
}).sort((a, b) => (b.day?.v || 0) - (a.day?.v || 0)).slice(0, 40);
return candidates.map(t => ({
  json: {
    ticker: t.ticker,
    close: t.day?.c,
    open: t.day?.o,
    high: t.day?.h,
    low: t.day?.l,
    volume: t.day?.v,
    prevClose: t.prevDay?.c,
    change_pct: t.todaysChangePerc
  }
}));

const base = $('Pre-Filter Candidates').item.json;
const results = $input.item.json.results || [];
if (results.length < 30) return { json: { ticker: base.ticker, sufficient_data: false } };
const allBars = results.slice().reverse();
const bars = allBars.filter(b => b != null && typeof b.o === 'number' && typeof b.h === 'number' && typeof b.l === 'number' && typeof b.c === 'number' && typeof b.v === 'number');
if (bars.length < 30) return { json: { ticker: base.ticker, sufficient_data: false } };
const n = bars.length;
const mean = arr => arr.reduce((a, b) => a + b, 0) / arr.length;
const fp = (v, d) => v != null && isFinite(v) ? parseFloat(v.toFixed(d)) : null;
function calcEMASeries(closes, period, count) {
  if (closes.length < 2) return [];
  const k = 2 / (period + 1);
  const seedLen = Math.min(period, closes.length);
  let ema = mean(closes.slice(0, seedLen));
  const series = [];
  for (let i = seedLen; i < closes.length; i++) { ema = closes[i] * k + ema * (1 - k); if (i >= closes.length - count) series.push(ema); }
  if (series.length === 0) series.push(ema);
  return series;
}
function calcRSISeries(closes, period, count) {
  const series = [];
  for (let end = closes.length - count; end <= closes.length - 1; end++) {
    const slice = closes.slice(Math.max(0, end - period * 2), end + 1);
    let gains = 0, losses = 0;
    for (let i = 1; i <= period && i < slice.length; i++) { const diff = slice[slice.length - i] - slice[slice.length - i - 1]; if (diff > 0) gains += diff; else losses -= diff; }
    const rs = (losses / period) === 0 ? 100 : (gains / period) / (losses / period);
    series.push(fp(100 - 100 / (1 + rs), 2));
  }
  return series;
}
function calcMACDSeries(closes, fast, slow, signal, count) {
  if (closes.length < slow + signal) return [];
  const kFast = 2 / (fast + 1), kSlow = 2 / (slow + 1);
  let ef = mean(closes.slice(0, fast)), es = mean(closes.slice(0, slow));
  const macdLines = [];
  for (let i = 0; i < closes.length; i++) { if (i >= fast) ef = closes[i] * kFast + ef * (1 - kFast); if (i >= slow) { es = closes[i] * kSlow + es * (1 - kSlow); macdLines.push(ef - es); } }
  if (macdLines.length < signal) return [];
  const kSig = 2 / (signal + 1);
  let sigEMA = mean(macdLines.slice(0, signal));
  const sigSeries = [];
  for (let i = signal; i < macdLines.length; i++) { sigEMA = macdLines[i] * kSig + sigEMA * (1 - kSig); if (i >= macdLines.length - count) sigSeries.push(sigEMA); }
  return macdLines.slice(-count).map((m, i) => ({ line: fp(m, 4), signal: fp(sigSeries[i] || 0, 4), histogram: fp(m - (sigSeries[i] || 0), 4) }));
}
function calcBBSeries(closes, period, mult, count) {
  const series = [];
  for (let i = closes.length - count; i < closes.length; i++) {
    if (i - period + 1 < 0) continue;
    const slice = closes.slice(i - period + 1, i + 1);
    const mid = mean(slice);
    const std = Math.sqrt(mean(slice.map(c => Math.pow(c - mid, 2))));
    const upper = mid + mult * std, lower = mid - mult * std, denom = upper - lower;
    series.push({ upper: fp(upper, 4), mid: fp(mid, 4), lower: fp(lower, 4), width: fp(mid > 0 ? (upper - lower) / mid : 0, 6), pct_b: fp(denom !== 0 ? (closes[i] - lower) / denom : 0.5, 4) });
  }
  return series;
}
function calcATR(bars, period) {
  if (bars.length < 2) return 0;
  return fp(mean(bars.slice(1).map((b, i) => Math.max((b.h||0)-(b.l||0), Math.abs((b.h||0)-(bars[i].c||0)), Math.abs((b.l||0)-(bars[i].c||0)))).slice(-period)), 4);
}
const closes = bars.map(b => b.c);
const COUNT = 6;
const ema200Series = calcEMASeries(closes, 200, 12);
if (ema200Series.length < 1) return { json: { ticker: base.ticker, sufficient_data: false } };
const ema200 = ema200Series[ema200Series.length - 1];
const ema200_10ago = ema200Series[Math.max(0, ema200Series.length - 11)];
const rsiSeries = calcRSISeries(closes, 14, COUNT);
const macdSeries = calcMACDSeries(closes, 12, 26, 9, COUNT);
const bbSeries = calcBBSeries(closes, 20, 2, COUNT);
const atr = calcATR(bars.slice(-16), 14);
if (!macdSeries.length || !bbSeries.length || !rsiSeries.length) return { json: { ticker: base.ticker, sufficient_data: false } };
const today = bars[n-1], bb = bbSeries[bbSeries.length-1], macd = macdSeries[macdSeries.length-1], rsi = rsiSeries[rsiSeries.length-1];
const volumes = bars.map(b => b.v || 0);
const volSlice = volumes.slice(-21, -1);
const volume_sma_20 = volSlice.length > 0 ? fp(mean(volSlice), 0) : 1;
const closes50 = closes.slice(-52, -2), closes20 = closes.slice(-22, -2), highs20 = bars.slice(-22,-1).map(b => b.h||0);
const recentHighs = closes.slice(-12);
const localHighIdx = recentHighs.reduce((maxI, c, i) => c > recentHighs[maxI] ? i : maxI, 0);
return { json: {
  sufficient_data: true, ticker: base.ticker,
  signal_date: new Date().toISOString().split('T')[0],
  close: fp(today.c,4), open: fp(today.o,4), high: fp(today.h,4), low: fp(today.l,4), volume_today: today.v||0,
  rsi_14: rsi, macd_line: macd.line, macd_signal: macd.signal, macd_histogram: macd.histogram,
  bb_upper: bb.upper, bb_mid: bb.mid, bb_lower: bb.lower, bb_width: bb.width, bb_pct_b: bb.pct_b,
  bb_width_20bar_min: fp(Math.min(...bbSeries.slice(-20).map(b => b.width||0)), 6),
  ema_200: fp(ema200,4), ema_200_10ago: fp(ema200_10ago,4), atr_14: atr,
  volume_sma_20: volume_sma_20, volume_vs_avg: fp((today.v||0)/(volume_sma_20||1), 2),
  low_3bar: fp(Math.min(...bars.slice(-3).map(b => b.l||Infinity)), 4),
  low_5bar: fp(Math.min(...bars.slice(-5).map(b => b.l||Infinity)), 4),
  prior_50bar_high: closes50.length > 0 ? fp(Math.max(...closes50),4) : fp(today.c,4),
  prior_20bar_low: closes20.length > 0 ? fp(Math.min(...closes20),4) : fp(today.c,4),
  high_20bar_max: highs20.length > 0 ? fp(Math.max(...highs20),4) : fp(today.h,4),
  bars_since_local_high: recentHighs.length - 1 - localHighIdx,
  macd_hist_last5: macdSeries.slice(-5).map(m => m.histogram),
  macd_line_last5: macdSeries.slice(-5).map(m => m.line),
  rsi_last5: rsiSeries.slice(-5),
  low_last5: bars.slice(-5).map(b => fp(b.l,4)),
  bb_pct_b_last3: bbSeries.slice(-3).map(b => b.pct_b)
}};

// Collect all passing ticker items into one array
const items = $input.all();
return [{ json: { tickers: items.map(i => i.json) } }];

const tickers = $input.first().json.tickers || [];
const signal_date = tickers[0]?.signal_date || new Date().toISOString().split('T')[0];
const tickerData = tickers.map(t => ({
  ticker: t.ticker,
  close: t.close, open: t.open, high: t.high, low: t.low,
  rsi: t.rsi_14, macd_line: t.macd_line, macd_hist: t.macd_histogram, macd_sig: t.macd_signal,
  bb_upper: t.bb_upper, bb_mid: t.bb_mid, bb_lower: t.bb_lower,
  bb_width: t.bb_width, bb_width_min: t.bb_width_20bar_min, bb_pct_b: t.bb_pct_b,
  ema200: t.ema_200, ema200_10ago: t.ema_200_10ago, atr: t.atr_14,
  vol_today: t.volume_today, vol_sma20: t.volume_sma_20, vol_vs_avg: t.volume_vs_avg,
  macd_hist_last5: t.macd_hist_last5, macd_line_last5: t.macd_line_last5,
  rsi_last5: t.rsi_last5, low_last5: t.low_last5, bb_pct_b_last3: t.bb_pct_b_last3,
  low_3bar: t.low_3bar, low_5bar: t.low_5bar,
  prior_50bar_high: t.prior_50bar_high, prior_20bar_low: t.prior_20bar_low,
  high_20bar: t.high_20bar_max, bars_since_high: t.bars_since_local_high
}));

const systemPrompt = 'You are a swing trade setup classifier. For EACH ticker in the input array determine: qualifies (true/false), setup_type, conviction (High/Med/Low), reasoning (2-3 sentences), entry_low, entry_high, stop, target. Respond ONLY with a JSON array, one object per ticker, same order as input. No preamble, no markdown.\n\nSETUP TYPES:\nmomentum_continuation: close>ema200, ema slope>=0.5% over 10 bars, low_5bar near bb_mid +/-1 ATR, MACD hist positive+expanding, rsi 45-65, bars_since_high<=10, volume asymmetry, stop<=1.5 ATR.\nema_pullback: low_3bar within 1.75% of ema200 AND reclaimed, MACD<0 hist improving, rsi 35-50, close<=bb_mid+0.5ATR.\nbb_squeeze_breakout: bb_width<=bb_width_min*1.10, close>bb_upper, vol_vs_avg>=1.75, MACD hist expanding, rsi 55-72, close>ema200.\nbb_mean_reversion: bb_pct_b<=0 on 1-2 bars only, extreme bar close in upper 67%, today bb_pct_b>0, rsi<35 turning up.\nmacd_crossover: MACD crossed above signal today or yesterday at line<=0, rsi 40-60, bb_pct_b 0-0.5, vol>1.1x.\nbreakout_retest: close within 2% above prior_50bar_high, vol<1.2x, macd_line>0, rsi 45-65, close>ema200, RR>=2.\n\nCONVICTION: Low=gates pass, Med=confirmation, High=Med+strong qualifier.\n\nRESPONSE FORMAT: [{"ticker":"X","qualifies":false,"setup_type":null,"conviction":null,"reasoning":null,"entry_low":null,"entry_high":null,"stop":null,"target":null}]';

const requestBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 4096,
  system: systemPrompt,
  messages: [{ role: 'user', content: 'Date: ' + signal_date + '. Evaluate: ' + JSON.stringify(tickerData) }]
};

return [{ json: { request_body: JSON.stringify(requestBody), indicators: tickers } }];

const raw = $input.first().json.content?.[0]?.text || '';
const indicators = $('Build Batch Prompt').first().json.indicators || [];
let results;
try {
  const clean = raw.replace(/```json|```/g, '').trim();
  results = JSON.parse(clean);
} catch (e) {
  return indicators.map(ind => ({ json: { qualifies: false, error: 'parse_failed', ticker: ind.ticker, _indicators: ind } }));
}
return results.map((result, i) => ({ json: { ...result, _indicators: indicators[i] || {} } }));
